21	import type { ParsedLogEntry } from "src/queries/useLogs";
22	
23	type VisibleItem = { entry: ParsedLogEntry; originalIndex: number };
24	
25	/**
26	 * Manages log group expand/collapse state and computes the list of
27	 * visible entries for the virtualizer. Handles nested groups and
28	 * auto-expanding collapsed groups when search navigates into them.
29	 */
30	export const useLogGroups = ({
31	  currentMatchLineIndex,
32	  expanded,
33	  parsedLogs,
34	  searchMatchIndices,
35	}: {
36	  currentMatchLineIndex?: number;
37	  expanded: boolean;
38	  parsedLogs: Array<ParsedLogEntry>;
39	  searchMatchIndices?: Set<number>;
40	}) => {
41	  // Build parent map for nested visibility checks
42	  const groupHeaders = parsedLogs.filter(
43	    (entry): entry is { group: NonNullable<ParsedLogEntry["group"]> } & ParsedLogEntry =>
44	      entry.group?.type === "header",
45	  );
46	  const allGroupIds = new Set(groupHeaders.map((entry) => entry.group.id));
47	  // eslint-disable-next-line react-hooks/exhaustive-deps -- React Compiler auto-memoizes this
48	  const groupParentMap = new Map<number, number | undefined>(
49	    groupHeaders.map((entry) => [entry.group.id, entry.group.parentId]),
50	  );
51	
52	  const [expandedGroups, setExpandedGroups] = useState<Set<number>>(() =>
53	    expanded ? new Set(allGroupIds) : new Set<number>(),
54	  );
55	
56	  // Sync expandedGroups when expanded prop changes (toggle all)
57	  useEffect(() => {
58	    if (expanded) {
59	      setExpandedGroups(new Set(allGroupIds));
60	    } else {
61	      setExpandedGroups(new Set<number>());
62	    }
63	    // Only react to the expanded prop, not allGroupIds
64	    // eslint-disable-next-line react-hooks/exhaustive-deps
65	  }, [expanded]);
66	
67	  const toggleGroup = (groupId: number) => {
68	    setExpandedGroups((prev) => {
69	      const next = new Set(prev);
70	
71	      if (next.has(groupId)) {
72	        next.delete(groupId);
73	      } else {
74	        next.add(groupId);
75	      }
76	
77	      return next;
78	    });
79	  };
80	
81	  // Check if all ancestors of a group are expanded
82	  const isGroupAncestryExpanded = (groupId: number): boolean => {
83	    const parentId = groupParentMap.get(groupId);
84	
85	    if (parentId === undefined) {
86	      return true;
87	    }
88	
89	    return expandedGroups.has(parentId) && isGroupAncestryExpanded(parentId);
90	  };
91	
92	  const isEntryVisible = (entry: ParsedLogEntry): boolean => {
93	    if (!entry.group) {
94	      return true;
95	    }
96	
97	    if (entry.group.type === "header") {
98	      return isGroupAncestryExpanded(entry.group.id);
99	    }
100	
101	    return expandedGroups.has(entry.group.id) && isGroupAncestryExpanded(entry.group.id);
102	  };
103	
104	  // Build visible items list with index mapping
105	  const visibleItems: Array<VisibleItem> = [];
106	  const originalToVisibleIndex = new Map<number, number>();
107	
108	  for (let idx = 0; idx < parsedLogs.length; idx += 1) {
109	    const entry = parsedLogs[idx];
110	
111	    if (entry && isEntryVisible(entry)) {
112	      originalToVisibleIndex.set(idx, visibleItems.length);
113	      visibleItems.push({ entry, originalIndex: idx });
114	    }
115	  }
116	
117	  // Map search match indices from original to visible indices
118	  const visibleSearchMatchIndices = searchMatchIndices
119	    ? new Set(
120	        [...searchMatchIndices]
121	          .map((idx) => originalToVisibleIndex.get(idx))
122	          .filter((idx): idx is number => idx !== undefined),
123	      )
124	    : undefined;
125	
126	  const visibleCurrentMatchIndex =
