129	  // Auto-expand group (and all ancestors) when search navigates to a match inside a collapsed group
130	  useEffect(() => {
131	    if (currentMatchLineIndex === undefined) {
132	      return;
133	    }
134	    const entry = parsedLogs[currentMatchLineIndex];
135	
136	    if (!entry?.group) {
137	      return;
138	    }
139	
140	    const groupsToExpand: Array<number> = [];
141	
142	    if (entry.group.type === "line" && !expandedGroups.has(entry.group.id)) {
143	      groupsToExpand.push(entry.group.id);
144	    }
145	
146	    // Walk up the parent chain
147	    let currentId: number | undefined = entry.group.id;
148	
149	    while (currentId !== undefined) {
150	      const parentId = groupParentMap.get(currentId);
151	
152	      if (parentId !== undefined && !expandedGroups.has(parentId)) {
153	        groupsToExpand.push(parentId);
154	      }
155	      currentId = parentId;
156	    }
157	
158	    if (groupsToExpand.length > 0) {
159	      setExpandedGroups((prev) => new Set([...prev, ...groupsToExpand]));
160	    }
161	  }, [currentMatchLineIndex, parsedLogs, expandedGroups, groupParentMap]);
