/**
 * Task instance context fields that are injected on every structured log line.
 * These are stripped from the per-line output and surfaced once in a dedicated
 * "Task Identity" preamble instead (see {@link renderTIContextPreamble}).
 */
export const tiContextFields: Array<string> = [
  "ti_id",
  "dag_id",
  "task_id",
  "run_id",
  "try_number",
  "map_index",
];

/**
 * Extract the task instance context (the fields listed in {@link tiContextFields})
 * from a list of structured log messages. Returns the first non-empty context found,
 * or `undefined` when none of the log lines carry any TI context fields.
 */
export const extractTIContext = (
  content: Array<string | StructuredLogMessage>,
): Record<string, unknown> | undefined => {
  for (const datum of content) {
    if (typeof datum === "string") {
      continue; // eslint-disable-line no-continue
    }

    const context: Record<string, unknown> = {};

    for (const field of tiContextFields) {
      if (Object.hasOwn(datum, field) && (datum as Record<string, unknown>)[field] !== undefined) {
        context[field] = (datum as Record<string, unknown>)[field];
      }
    }

    if (Object.keys(context).length > 0) {
      return context;
    }
  }

  return undefined;
};

/**
 * Render a preamble that summarizes the task identity context fields present in
 * `context`. Only fields that are both in {@link tiContextFields} and present in
 * the supplied context object are rendered.
 *
 * - In "text" mode, returns a string of space-joined `key=value` pairs, optionally
 *   prefixed with `${label} `.
 * - In "jsx" mode, returns a JSX element rendering the label (if provided) followed
 *   by a `key=value` entry per present field.
 */
export function renderTIContextPreamble(
  context: Record<string, unknown>,
  renderingMode: "jsx" | "text",
  label: string,
): string;
export function renderTIContextPreamble(
  context: Record<string, unknown>,
  renderingMode?: "jsx",
  label?: string,
): JSX.Element;
export function renderTIContextPreamble(
  context: Record<string, unknown>,
  renderingMode: "jsx" | "text" = "jsx",
  label?: string,
): JSX.Element | string {
  const entries = tiContextFields
    .filter((field) => Object.hasOwn(context, field) && context[field] !== undefined)
    .map((field) => {
      const val = context[field] as boolean | number | object | string | null;

      return [field, val instanceof Object ? JSON.stringify(val) : val] as const;
    });

  if (renderingMode === "text") {
    const pairs = entries.map(([key, val]) => `${key}=${val}`).join(" ");

    return label === undefined ? pairs : `${label} ${pairs}`;
  }

