        <React.Fragment key={`ti_frag_${key}`}>
          <React.Fragment> </React.Fragment>
          <span data-key={key}>
            <chakra.span color="fg.info">{key}</chakra.span>=<span data-value>{val}</span>
          </span>
        </React.Fragment>
      ))}
    </chakra.span>
